-- ==========================================================================
-- 49_library_mock.sql —— 公共库 mock 数据（可重复执行）
--
-- 规模：靶点 24 / 小分子 19 / 抗体 10
-- 来源：
--   · 靶点序列、蛋白名、PDB 交叉引用 —— UniProt REST（不手写序列）
--   · 结构与分辨率 —— RCSB data API 校验，只保留覆盖 ≥50% 残基的条目；
--     低于 50% 的（多为单个结构域或几残基短肽）不计入「有实验结构」，
--     相应靶点只挂 AlphaFold 全长模型，完备度如实显示为「仅预测结构」
--   · 小分子 SMILES —— PubChem（按通用名查 CID，SMILES 与 CID 一一对应）
--   · 描述符 —— RDKit 2026.03.6 实算（与平台评估阶段同一引擎），非 PubChem 抄数
--   · 抗体 VH/VL —— PDB Fab 晶体结构链，sequence_source=PDB_DERIVED
--
-- 依赖 48_library.sql 已执行（library_dataset / library_item / library_tag 存在）
-- ==========================================================================

SET NAMES utf8mb4;

SET @ds_target := (SELECT `id` FROM `library_dataset` WHERE `code` = 'PUBLIC_TARGET');
SET @ds_mol    := (SELECT `id` FROM `library_dataset` WHERE `code` = 'PUBLIC_MOLECULE');
SET @ds_seq    := (SELECT `id` FROM `library_dataset` WHERE `code` = 'PUBLIC_SEQUENCE');

-- --------------------------------------------------------------------------
-- 0. 标签字典适用范围扩展
--
-- 分子与抗体也要按适应症/阶段筛选，否则分子库只能按「阶段」一个维度过滤。
-- 只扩 item_types，不新增标签组 —— 组的概念保持与 §4 一致。
-- --------------------------------------------------------------------------
UPDATE `library_tag` SET `item_types` = 'TARGET,MOLECULE'          WHERE `code` LIKE 'DISEASE\_%' AND `item_types` = 'TARGET';
UPDATE `library_tag` SET `item_types` = 'TARGET,MOLECULE,SEQUENCE'  WHERE `code` LIKE 'PHASE\_%'   AND `item_types` = 'TARGET,MOLECULE';
UPDATE `library_tag` SET `item_types` = 'TARGET,SEQUENCE'           WHERE `code` = 'SOURCE_PDB';

-- 分子/抗体的结构完备度用独立标签：套用「有实验结构」会在分子卡片上写着「无实验结构」，语义错位
SELECT * FROM (SELECT 'QUALITY_STRUCT_KNOWN' AS `code`, '结构已确证' AS `label`, 'QUALITY' AS `tag_group`,
                     'DERIVED' AS `tag_type`, 'MOLECULE' AS `item_types`, 75 AS `sort_no`, 1 AS `builtin`) AS t
WHERE NOT EXISTS (SELECT 1 FROM `library_tag` lt WHERE lt.`code` = t.`code`);

-- --------------------------------------------------------------------------
-- 1. 临时载荷表（TEMPORARY：脚本结束自动消失，不污染业务库）
-- --------------------------------------------------------------------------
CREATE TEMPORARY TABLE `tmp_seed_target` (
    `acc`          varchar(20)  NOT NULL PRIMARY KEY,
    `gene`         varchar(100) NOT NULL,
    `zh`           varchar(200) NOT NULL,
    `ptype`        varchar(80)  NOT NULL,
    `pfamily`      varchar(200) NOT NULL,
    `family`       varchar(64)  NOT NULL,
    `diseases`     varchar(200) NOT NULL,
    `modality`     varchar(64)  NOT NULL,
    `phase`        varchar(64)  NOT NULL,
    `pathway`      varchar(500) NOT NULL,
    `related`      varchar(500) NOT NULL,
    `drugs`        varchar(500) NOT NULL,
    `descr`        text         NOT NULL,
    `safety`       varchar(200) NOT NULL,
    `seq`          mediumtext   NOT NULL,
    `seq_len`      int          NOT NULL,
    `pdb_ids`      varchar(200) DEFAULT NULL,
    `quality`      varchar(32)  NOT NULL,
    `seed_struct`  tinyint      NOT NULL,
    `disease_area` varchar(200) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TEMPORARY TABLE `tmp_seed_struct` (
    `acc`          varchar(20)  NOT NULL,
    `source`       varchar(20)  NOT NULL,
    `source_key`   varchar(80)  NOT NULL,
    `pdb_id`       varchar(10)  DEFAULT NULL,
    `chain`        varchar(10)  DEFAULT NULL,
    `method`       varchar(40)  DEFAULT NULL,
    `resolution`   decimal(5,2) DEFAULT NULL,
    `is_preferred` tinyint      NOT NULL,
    PRIMARY KEY (`acc`, `source`, `source_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TEMPORARY TABLE `tmp_seed_mol` (
    `inn`       varchar(100)  NOT NULL PRIMARY KEY,
    `zh`        varchar(200)  NOT NULL,
    `formula`   varchar(100)  NOT NULL,
    `inchikey`  char(27)      NOT NULL,
    `smiles`    varchar(2000) NOT NULL,
    `canonical` varchar(2000) NOT NULL,
    `mw`        decimal(9,3)  NOT NULL,
    `logp`      decimal(7,3)  NOT NULL,
    `tpsa`      decimal(7,3)  NOT NULL,
    `hbd`       int           NOT NULL,
    `hba`       int           NOT NULL,
    `rot`       int           NOT NULL,
    `qed`       decimal(5,4)  NOT NULL,
    `pains`     int           NOT NULL,
    `note`      varchar(500)  NOT NULL,
    UNIQUE KEY `uk_tmp_mol_inchikey` (`inchikey`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TEMPORARY TABLE `tmp_seed_ab` (
    `inn`     varchar(100) NOT NULL PRIMARY KEY,
    `zh`      varchar(200) NOT NULL,
    `gene`    varchar(100) NOT NULL,
    `pdb`     varchar(10)  NOT NULL,
    `heavy`   mediumtext   NOT NULL,
    `light`   mediumtext   NOT NULL,
    `vh`      int          NOT NULL,
    `vl`      int          NOT NULL,
    `hash`    char(64)     NOT NULL,
    `note`    varchar(500) NOT NULL,
    UNIQUE KEY `uk_tmp_ab_hash` (`hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TEMPORARY TABLE `tmp_seed_tag` (
    `key1` varchar(64) NOT NULL COMMENT 'accession / inchikey / sequence_hash',
    `code` varchar(64) NOT NULL,
    PRIMARY KEY (`key1`, `code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------------------------
-- 2. 修正既有靶点的序列
--
-- 库里 EGFR / ACE2 / TP53 的 sequence 是 24/51/61 字符的示意片段，而真实长度为
-- 1210/805/393。DTI 与 PPI 的特征按序列长度算，片段会让预测失真；
-- 这里用 UniProt 规范序列覆盖，并把 pdb_ids 之外的结构交给 4. 处理。
-- 结构行一律不动：TP53「无结构」是基线预检 NO_STRUCTURE 的演示状态，
-- 给补上 AlphaFold 模型会把 e2e-target-library 的 readiness.tp53 断言打穿。
-- --------------------------------------------------------------------------
UPDATE `target` t
JOIN `tmp_seed_target` s ON s.`acc` = t.`uniprot_id`
SET t.`sequence` = s.`seq`,
    t.`sequence_length` = s.`seq_len`
WHERE t.`dataset_id` = @ds_target AND t.`variant_code` = '';

-- --------------------------------------------------------------------------
-- 3. 新增靶点（只加 seed_struct = 1 的 21 个，既有 3 个已在库内）
-- --------------------------------------------------------------------------
     `family`, `pathway`, `disease_area`, `related_diseases`, `known_drugs`, `sequence`,
     `sequence_length`, `pdb_ids`, `status`, `source`, `description`, `variant_code`)
SELECT @ds_target, s.`acc`, s.`gene`, s.`zh`, s.`gene`, 'human', s.`ptype`,
       s.`pfamily`, s.`pathway`, s.`disease_area`, s.`related`, s.`drugs`, s.`seq`,
       s.`seq_len`, s.`pdb_ids`, 'supported', 'UNIPROT', s.`descr`, ''
FROM `tmp_seed_target` s
WHERE s.`seed_struct` = 1
  AND NOT EXISTS (SELECT 1 FROM `target` t
                   WHERE t.`dataset_id` = @ds_target AND t.`uniprot_id` = s.`acc` AND t.`variant_code` = '');

-- 新靶点的 PDB 编号一并回填展示列；既有 3 个靶点的 pdb_ids 保持原样
-- （TP53 在库里没有任何结构行，给它填一个结构域编号会让「无结构」的展示自相矛盾）
UPDATE `target` t
JOIN `tmp_seed_target` s ON s.`acc` = t.`uniprot_id`
SET t.`pdb_ids` = s.`pdb_ids`
WHERE t.`dataset_id` = @ds_target AND t.`variant_code` = ''
  AND s.`seed_struct` = 1 AND s.`pdb_ids` IS NOT NULL;

-- --------------------------------------------------------------------------
-- 4. 结构：只挂覆盖率 ≥50% 的 PDB 条目 + 每个靶点一个 AlphaFold 全长模型
-- --------------------------------------------------------------------------
     `resolution`, `ligand_count`, `pocket_count`, `is_preferred`)
SELECT t.`id`, st.`pdb_id`, st.`chain`, st.`source`, st.`source_key`, st.`method`,
       st.`resolution`, 0, 0, st.`is_preferred`
FROM `tmp_seed_struct` st
JOIN `target` t
  ON t.`uniprot_id` = st.`acc`
 AND t.`dataset_id` = @ds_target
 AND t.`variant_code` = ''
WHERE NOT EXISTS (SELECT 1 FROM `target_structure` x
                   WHERE x.`target_id` = t.`id`
                     AND x.`source` = st.`source`
                     AND x.`source_key` = st.`source_key`);

-- --------------------------------------------------------------------------
-- 5. 小分子：PubChem SMILES + RDKit 描述符
-- --------------------------------------------------------------------------
     `inchikey`, `mw`, `logp`, `tpsa`, `hbd`, `hba`, `rotatable`, `qed`, `pains_hits`, `note`)
SELECT @ds_mol, 'SMALL_MOLECULE', s.`inchikey`, s.`zh`, s.`smiles`, s.`canonical`,
       s.`inchikey`, s.`mw`, s.`logp`, s.`tpsa`, s.`hbd`, s.`hba`, s.`rot`, s.`qed`, s.`pains`, s.`note`
FROM `tmp_seed_mol` s
WHERE NOT EXISTS (SELECT 1 FROM `library_molecule` m
                   WHERE m.`dataset_id` = @ds_mol AND m.`dedup_key` = s.`inchikey`);

-- --------------------------------------------------------------------------
-- 6. 抗体：PDB Fab 的重链/轻链序列
-- --------------------------------------------------------------------------
     `light_chain`, `sequence_length`, `sequence_source`, `note`)
SELECT @ds_seq, 'ANTIBODY', s.`hash`, s.`zh`, s.`hash`, s.`heavy`, s.`light`,
       s.`vh` + s.`vl`, 'PDB_DERIVED', s.`note`
FROM `tmp_seed_ab` s
WHERE NOT EXISTS (SELECT 1 FROM `library_molecule` m
                   WHERE m.`dataset_id` = @ds_seq AND m.`dedup_key` = s.`hash`);

-- --------------------------------------------------------------------------
-- 7. 检索投影 library_item（幂等 upsert）
--
-- quality_level 对分子/抗体用 MOLECULE_READY / SEQUENCE_READY：
-- 套用「有实验结构」会让分子卡片写着「无实验结构」，把靶点的完备度语义搬到别处。
-- --------------------------------------------------------------------------
SELECT t.`dataset_id`, 'TARGET', t.`id`, COALESCE(t.`gene_name`, t.`name`),
       CONCAT_WS(' · ', t.`chinese_name`, t.`uniprot_id`),
       TRIM(BOTH ' ' FROM CONCAT_WS(' ', t.`name`, t.`chinese_name`, t.`gene_name`,
            t.`uniprot_id`, t.`family`, t.`target_type`, t.`disease_area`,
            LEFT(t.`description`, 160))),
       s.`quality`
FROM `target` t
JOIN `tmp_seed_target` s ON s.`acc` = t.`uniprot_id`
WHERE t.`dataset_id` = @ds_target AND t.`variant_code` = ''
ON DUPLICATE KEY UPDATE
    `title` = VALUES(`title`),
    `subtitle` = VALUES(`subtitle`),
    `search_text` = VALUES(`search_text`),
    `quality_level` = VALUES(`quality_level`),
    `deleted` = 0;

SELECT m.`dataset_id`, 'MOLECULE', m.`id`, s.`zh`,
       CONCAT_WS(' · ', s.`inn`, s.`formula`),
       TRIM(BOTH ' ' FROM CONCAT_WS(' ', s.`inn`, s.`zh`, s.`formula`, m.`inchikey`,
            REPLACE(SUBSTRING_INDEX(m.`note`, '（', 1), ' ', ' '))),
       'MOLECULE_READY'
FROM `library_molecule` m
JOIN `tmp_seed_mol` s ON s.`inchikey` = TRIM(m.`dedup_key`)
WHERE m.`dataset_id` = @ds_mol
ON DUPLICATE KEY UPDATE
    `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`),
    `search_text` = VALUES(`search_text`), `quality_level` = VALUES(`quality_level`), `deleted` = 0;

SELECT m.`dataset_id`, 'SEQUENCE', m.`id`, s.`zh`,
       CONCAT_WS(' · ', '抗体', s.`gene`),
       TRIM(BOTH ' ' FROM CONCAT_WS(' ', s.`inn`, s.`zh`, s.`gene`, s.`pdb`,
            REPLACE(SUBSTRING_INDEX(m.`note`, '（', 1), ' ', ' '))),
       'SEQUENCE_READY'
FROM `library_molecule` m
JOIN `tmp_seed_ab` s ON s.`hash` = TRIM(m.`dedup_key`)
WHERE m.`dataset_id` = @ds_seq
ON DUPLICATE KEY UPDATE
    `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`),
    `search_text` = VALUES(`search_text`), `quality_level` = VALUES(`quality_level`), `deleted` = 0;

-- --------------------------------------------------------------------------
-- 8. 标签重建
--
-- 公共数据集里的标签全部是 CURATED / DERIVED，没有用户可编辑的 USER 标签；
-- 因此可以整体重算。保留 USER_ 前缀是为了将来公共条目支持协作标注时不误删。
-- --------------------------------------------------------------------------
DELETE lit FROM `library_item_tag` lit
JOIN `library_item` li ON li.`id` = lit.`item_id`
WHERE li.`dataset_id` IN (@ds_target, @ds_mol, @ds_seq)
  AND lit.`tag_code` NOT LIKE 'USER\_%';

-- 8.1 建档标签：家族 / 适应症 / 成药模态 / 临床阶段 / 安全性
SELECT DISTINCT li.`id`, st.`code`
FROM `tmp_seed_tag` st
JOIN `target` t
  ON t.`uniprot_id` = st.`key1`
 AND t.`dataset_id` = @ds_target
 AND t.`variant_code` = ''
JOIN `library_item` li ON li.`item_type` = 'TARGET' AND li.`entity_id` = t.`id`;

SELECT DISTINCT li.`id`, st.`code`
FROM `tmp_seed_tag` st
JOIN `library_molecule` m ON TRIM(m.`dedup_key`) = st.`key1` AND m.`dataset_id` IN (@ds_mol, @ds_seq)
JOIN `library_item` li ON li.`entity_id` = m.`id` AND li.`item_type` IN ('MOLECULE', 'SEQUENCE');

-- 8.2 派生标签：来源
SELECT li.`id`, 'SOURCE_UNIPROT' FROM `library_item` li WHERE li.`dataset_id` = @ds_target;

SELECT DISTINCT li.`id`, 'SOURCE_PDB'
FROM `library_item` li
JOIN `target_structure` s ON s.`target_id` = li.`entity_id` AND s.`deleted` = 0
WHERE li.`dataset_id` = @ds_target AND s.`source` = 'PDB';

SELECT li.`id`, 'SOURCE_CHEMBL' FROM `library_item` li WHERE li.`dataset_id` = @ds_mol;

SELECT li.`id`, 'SOURCE_PDB' FROM `library_item` li WHERE li.`dataset_id` = @ds_seq;

-- 8.3 派生标签：完备度
SELECT li.`id`,
       CASE li.`quality_level`
           WHEN 'EXPERIMENTAL_STRUCTURE' THEN 'QUALITY_EXP_STRUCT'
           WHEN 'PREDICTED_ONLY'         THEN 'QUALITY_PRED_STRUCT'
           WHEN 'MOLECULE_READY'         THEN 'QUALITY_STRUCT_KNOWN'
           ELSE 'QUALITY_NO_STRUCT'
       END
FROM `library_item` li WHERE li.`dataset_id` = @ds_target;

SELECT li.`id`, 'QUALITY_STRUCT_KNOWN' FROM `library_item` li WHERE li.`dataset_id` = @ds_mol;

SELECT li.`id`, 'QUALITY_FULL_SEQ' FROM `library_item` li WHERE li.`dataset_id` = @ds_seq;

-- 靶点序列完备度：与 4. 的判定同源（sequence_length 真实长度）
SELECT li.`id`, 'QUALITY_FULL_SEQ'
FROM `library_item` li JOIN `target` t ON t.`id` = li.`entity_id`
WHERE li.`dataset_id` = @ds_target AND COALESCE(t.`sequence_length`, 0) >= 100;

SELECT li.`id`, 'QUALITY_FRAG_SEQ'
FROM `library_item` li JOIN `target` t ON t.`id` = li.`entity_id`
WHERE li.`dataset_id` = @ds_target AND COALESCE(t.`sequence_length`, 0) < 100;

-- 8.4 派生标签：可用能力
SELECT li.`id`, 'READY_DTI'
FROM `library_item` li JOIN `target` t ON t.`id` = li.`entity_id`
WHERE li.`dataset_id` = @ds_target AND COALESCE(t.`sequence_length`, 0) >= 20;

SELECT li.`id`, 'READY_PPI'
FROM `library_item` li JOIN `target` t ON t.`id` = li.`entity_id`
WHERE li.`dataset_id` = @ds_target AND COALESCE(t.`sequence_length`, 0) >= 100;

SELECT li.`id`, 'READY_POCKET'
FROM `library_item` li
WHERE li.`dataset_id` = @ds_target AND li.`quality_level` = 'EXPERIMENTAL_STRUCTURE';

SELECT li.`id`, 'READY_GENERATE'
FROM `library_item` li
JOIN `tmp_seed_target` s ON s.`acc` = (SELECT t2.`uniprot_id` FROM `target` t2 WHERE t2.`id` = li.`entity_id`)
WHERE li.`dataset_id` = @ds_target
  AND li.`quality_level` = 'EXPERIMENTAL_STRUCTURE'
  AND s.`modality` IN ('MODALITY_SMALL', 'MODALITY_BOTH');

SELECT li.`id`, 'READY_DTI' FROM `library_item` li WHERE li.`dataset_id` = @ds_mol;

SELECT li.`id`, 'READY_PPI' FROM `library_item` li WHERE li.`dataset_id` = @ds_seq;

SELECT li.`id`, 'SAFETY_IMMUNO' FROM `library_item` li WHERE li.`dataset_id` = @ds_seq;

-- --------------------------------------------------------------------------
-- 9. 同步 item_count（列表页的「N 条」直接读这一列，不做实时 count）
-- --------------------------------------------------------------------------
UPDATE `library_dataset` d
SET d.`item_count` = (SELECT COUNT(*) FROM `library_item` li
                       WHERE li.`dataset_id` = d.`id` AND li.`deleted` = 0)
WHERE d.`code` IN ('PUBLIC_TARGET', 'PUBLIC_MOLECULE', 'PUBLIC_SEQUENCE');

-- --------------------------------------------------------------------------
-- 10. 自检（执行后会打印，数字对不上说明脚本没跑完）
-- --------------------------------------------------------------------------
SELECT 'dataset' AS item, COUNT(*) AS value FROM `library_dataset` WHERE `code` LIKE 'PUBLIC\_%'
UNION ALL SELECT 'target', COUNT(*) FROM `target` WHERE `dataset_id` = @ds_target AND `deleted` = 0
UNION ALL SELECT 'structure', COUNT(*) FROM `target_structure` s JOIN `target` t ON t.`id` = s.`target_id` WHERE t.`dataset_id` = @ds_target AND s.`deleted` = 0
UNION ALL SELECT 'molecule', COUNT(*) FROM `library_molecule` WHERE `dataset_id` = @ds_mol AND `deleted` = 0
UNION ALL SELECT 'antibody', COUNT(*) FROM `library_molecule` WHERE `dataset_id` = @ds_seq AND `deleted` = 0
UNION ALL SELECT 'library_item', COUNT(*) FROM `library_item` WHERE `dataset_id` IN (@ds_target, @ds_mol, @ds_seq) AND `deleted` = 0
UNION ALL SELECT 'item_tag', COUNT(*) FROM `library_item_tag` lit JOIN `library_item` li ON li.`id` = lit.`item_id` WHERE li.`dataset_id` IN (@ds_target, @ds_mol, @ds_seq);
