INSERT INTO `tmp_seed_target` VALUES
('P00533', 'EGFR', '表皮生长因子受体', '受体酪氨酸激酶', 'ErbB 家族', 'FAMILY_KINASE', 'DISEASE_ONCOLOGY', 'MODALITY_BOTH', 'PHASE_APPROVED', 'EGFR/RAS/MAPK · PI3K/AKT', '非小细胞肺癌；结直肠癌；头颈鳞癌', '吉非替尼；厄洛替尼；奥希替尼', 'ERBB 家族受体酪氨酸激酶，配体结合后经 RAS-MAPK 与 PI3K-AKT 驱动增殖。L858R 与外显子 19 缺失是 NSCLC 主要驱动基因，也是本平台 DTI 与口袋对接的基准靶点。', '', '', 1210, NULL, 'EXPERIMENTAL_STRUCTURE', 0, '肿瘤'),
('P04626', 'ERBB2', '受体酪氨酸蛋白激酶 erbB-2', '受体酪氨酸激酶', 'ErbB 家族', 'FAMILY_KINASE', 'DISEASE_ONCOLOGY', 'MODALITY_BIO', 'PHASE_APPROVED', 'ERBB signaling', '乳腺癌；胃癌；胃食管结合部腺癌', '曲妥珠单抗；帕妥珠单抗；拉帕替尼', 'HER2 无已知高亲和配体，靠与其他 ERBB 成员异源二聚化驱动信号；扩增/过表达见于约 20% 乳腺癌，是抗体偶联药物的主战场。', '', '', 1255, NULL, 'PREDICTED_ONLY', 1, '肿瘤'),
('P00519', 'ABL1', '酪氨酸蛋白激酶 ABL1', '非受体酪氨酸激酶', 'ABL 家族', 'FAMILY_KINASE', 'DISEASE_ONCOLOGY', 'MODALITY_SMALL', 'PHASE_APPROVED', 'BCR-ABL · RAS/MAPK', '慢性髓性白血病；Ph+ 急性淋巴细胞白血病', '伊马替尼；达沙替尼；尼洛替尼', 'BCR-ABL 融合是 CML 的定义性驱动事件；T315I 看门残基突变是二代/三代抑制剂的分水岭，适合做耐药变体建模练习。', '', '', 1130, NULL, 'PREDICTED_ONLY', 1, '肿瘤'),
('O60674', 'JAK2', '酪氨酸蛋白激酶 JAK2', '非受体酪氨酸激酶', 'JAK 家族', 'FAMILY_KINASE', 'DISEASE_IMMUNE', 'MODALITY_SMALL', 'PHASE_APPROVED', 'JAK-STAT', '骨髓纤维化；真性红细胞增多症；移植物抗宿主病', '芦可替尼；菲达替尼；巴瑞替尼', 'JAK2 V617F 是骨髓增殖性肿瘤的核心突变，持续激活 JAK-STAT；也是细胞因子风暴通路的关键节点。', '', '', 1132, NULL, 'PREDICTED_ONLY', 1, '免疫'),
('P11802', 'CDK4', '细胞周期蛋白依赖性激酶 4', '丝氨酸/苏氨酸激酶', 'CDK 家族', 'FAMILY_KINASE', 'DISEASE_ONCOLOGY', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Cell cycle G1/S', '激素受体阳性乳腺癌；脂肪肉瘤', '哌柏西利；瑞波西利；阿贝西利', '与 Cyclin D 结合后磷酸化 RB1 解除 G1 期阻滞；CDK4/6 抑制剂是 HR+/HER2- 乳腺癌的标准联合用药。', '', '', 303, '9CSK,2W96', 'EXPERIMENTAL_STRUCTURE', 1, '肿瘤'),
('P07550', 'ADRB2', 'β2 肾上腺素能受体', 'G 蛋白偶联受体', '肾上腺素能受体家族', 'FAMILY_GPCR', 'DISEASE_RESPIR', 'MODALITY_SMALL', 'PHASE_APPROVED', 'cAMP/PKA', '哮喘；慢性阻塞性肺疾病', '沙丁胺醇；福莫特罗；沙美特罗', '经典 Gs 偶联 GPCR，是吸入型支气管扩张剂的靶点；G16R 等多态性影响受体下调速度，适合做 GPCR 结构建模的入门靶点。', '', '', 413, '8W1V,5JQH', 'EXPERIMENTAL_STRUCTURE', 1, '呼吸'),
('P14416', 'DRD2', '多巴胺 D2 受体', 'G 蛋白偶联受体', '多巴胺受体家族', 'FAMILY_GPCR', 'DISEASE_NEURO', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Dopamine/cAMP', '精神分裂症；帕金森病；抽动障碍', '氟哌啶醇；利培酮；阿立哌唑', 'Gi 偶联 GPCR，抗精神病药的主要结合位点；D2 占位率与锥体外系反应相关，是安全性窗口窄的典型靶点。', '', '', 443, '9BS9', 'EXPERIMENTAL_STRUCTURE', 1, '神经'),
('P35372', 'OPRM1', 'μ 型阿片受体', 'G 蛋白偶联受体', '阿片受体家族', 'FAMILY_GPCR', 'DISEASE_NEURO', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Opioid/cAMP', '中重度疼痛；阿片使用障碍', '吗啡；芬太尼；丁丙诺啡', '镇痛药的核心靶点，同时介导呼吸抑制与耐受；A118G 多态性影响镇痛效能，是「效力与安全性权衡」的标准案例。', '', '', 400, '8EFO,8EF6', 'EXPERIMENTAL_STRUCTURE', 1, '神经'),
('P30556', 'AGTR1', '血管紧张素 II 受体 1 型', 'G 蛋白偶联受体', '血管紧张素受体家族', 'FAMILY_GPCR', 'DISEASE_CARDIO', 'MODALITY_SMALL', 'PHASE_APPROVED', 'RAAS', '高血压；心力衰竭；糖尿病肾病', '氯沙坦；缬沙坦；厄贝沙坦', '肾素-血管紧张素系统的效应受体，AT1 拮抗剂是心血管一线用药；与 ACE2/Ang(1-7) 反向通路构成本库内部的一组对立靶点。', '', '', 359, '6DO1,8TH3', 'EXPERIMENTAL_STRUCTURE', 1, '心血管'),
('P51681', 'CCR5', 'C-C 趋化因子受体 5 型', 'G 蛋白偶联受体', '趋化因子受体家族', 'FAMILY_GPCR', 'DISEASE_INFECTION', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Chemokine signaling', 'HIV-1 感染；移植物抗宿主病', '马拉维若', 'HIV-1 嗜性受体的主要共受体，CCR5-Δ32 纯合个体天然抗感染；趋化因子受体类 GPCR 的构象选择性拮抗剂代表。', '', '', 352, NULL, 'PREDICTED_ONLY', 1, '感染'),
('Q12809', 'KCNH2', '电压门控钾通道亚家族 H 成员 2（hERG）', '离子通道', '电压门控钾通道 Kv11 家族', 'FAMILY_IONCHAN', 'DISEASE_CARDIO', 'MODALITY_NONE', 'PHASE_NONE', 'Cardiac repolarization (IKr)', '长 QT 综合征 2 型；药物诱导性心律失常', '无获批药物（安全性脱靶靶点）', 'hERG 是药物心脏安全性的首要脱靶靶点，抑制 IKr 会延长 QT 间期并诱发尖端扭转型室速。本库把它放进公共数据集，用于让「风险关注点」与库筛选连通：先看分子是否抑制 hERG，再谈疗效。', 'SAFETY_HERG,SAFETY_OFFTARGET', '', 1159, '8ZYP,8ZYN', 'EXPERIMENTAL_STRUCTURE', 1, '心血管'),
('Q14524', 'SCN5A', '电压门控钠通道 α 亚基 5（Nav1.5）', '离子通道', '电压门控钠通道 Nav1 家族', 'FAMILY_IONCHAN', 'DISEASE_CARDIO', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Cardiac action potential phase 0', 'Brugada 综合征；长 QT 综合征 3 型；心房颤动', '氟卡尼；雷诺嗪；美西律', '心肌快钠通道，决定动作电位上升支；功能缺失与功能获得分别对应 Brugada 与 LQT3，是同一离子通道上双向表型的经典例子。', '', '', 2016, '6LQA', 'EXPERIMENTAL_STRUCTURE', 1, '心血管'),
('P13569', 'CFTR', '囊性纤维化跨膜传导调节因子', 'ABC 转运体/氯离子通道', 'ABC 转运体家族', 'FAMILY_IONCHAN', 'DISEASE_RARE,DISEASE_RESPIR', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Chloride transport', '囊性纤维化；先天性双侧输精管缺如', '依伐卡托；卢马卡托；依伐卡托/卢马卡托复方', '唯一可用小分子纠正子+增效剂组合治疗的离子通道病；F508del 是最常见突变，需要两个不同机制的小分子协同，是「联合用药必要性」的教科书案例。', '', '', 1480, NULL, 'PREDICTED_ONLY', 1, '罕见病 · 呼吸'),
('P14867', 'GABRA1', 'GABA-A 受体 α1 亚基', '配体门控离子通道', 'GABA-A 受体家族', 'FAMILY_IONCHAN', 'DISEASE_NEURO', 'MODALITY_SMALL', 'PHASE_APPROVED', 'GABAergic inhibition', '癫痫；焦虑障碍；失眠', '地西泮；唑吡坦；苯巴比妥', '抑制性神经传递主受体，苯二氮平类结合位点位于 α/γ 界面；耐受与依赖风险来自受体亚基组成改变。', '', '', 456, NULL, 'PREDICTED_ONLY', 1, '神经'),
('P56817', 'BACE1', 'β 分泌酶 1（β-site APP cleaving enzyme）', '天冬氨酸蛋白酶', '天冬氨酸蛋白酶家族', 'FAMILY_PROTEASE', 'DISEASE_NEURO', 'MODALITY_SMALL', 'PHASE_3', 'APP processing / Aβ 生成', '阿尔茨海默病', '维鲁贝司他（III 期终止）；埃塞司他', 'Aβ 生成的限速酶，理论上是最上游的 AD 靶点，但多项 III 期因疗效不足或肝毒性终止——本库保留它就是为了呈现「机制正确不等于临床成功」的证据链。', 'SAFETY_HEPATO', '', 501, '1FKN', 'EXPERIMENTAL_STRUCTURE', 1, '神经'),
('P14780', 'MMP9', '基质金属蛋白酶 9', '锌依赖性内肽酶', '基质金属蛋白酶家族', 'FAMILY_PROTEASE', 'DISEASE_INFLAMM,DISEASE_ONCOLOGY', 'MODALITY_SMALL', 'PHASE_PRECLIN', 'ECM remodeling', '类风湿关节炎；肿瘤侵袭转移；炎症性肠病', '无获批药物', '明胶酶 B，降解 IV 型胶原参与基底膜破坏；广谱 MMP 抑制剂因骨骼肌综合征失败，选择性抑制与结构锌指区分是核心难点。', '', '', 707, NULL, 'PREDICTED_ONLY', 1, '炎症 · 肿瘤'),
('P27487', 'DPP4', '二肽基肽酶 4', '丝氨酸蛋白酶', '二肽基肽酶家族', 'FAMILY_PROTEASE', 'DISEASE_METABOLIC', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Incretin / GLP-1 降解', '2 型糖尿病', '西格列汀；沙格列汀；利格列汀', '降解 GLP-1 与 GIP 的丝氨酸蛋白酶，抑制剂通过延长内源性肠促胰素作用降糖；共价抑制剂与可逆抑制剂的动力学差异是关键设计点。', '', '', 766, '1PFQ,1NU6', 'EXPERIMENTAL_STRUCTURE', 1, '代谢'),
('P03372', 'ESR1', '雌激素受体 α', '核受体', '核受体 NR3A 家族', 'FAMILY_NUCLEAR', 'DISEASE_ONCOLOGY', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Estrogen signaling', '激素受体阳性乳腺癌；子宫内膜癌', '他莫昔芬；氟维司群；依西美坦（间接）', '配体激活的转录因子，AF2 共激活因子结合口袋的构象差异决定了激动/拮抗；ESR1 Y537S 等配体结合域突变是内分泌耐药主因。', '', '', 595, NULL, 'PREDICTED_ONLY', 1, '肿瘤'),
('P10275', 'AR', '雄激素受体', '核受体', '核受体 NR3C 家族', 'FAMILY_NUCLEAR', 'DISEASE_ONCOLOGY', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Androgen signaling', '前列腺癌；肯尼迪病（SBMA）', '恩杂鲁胺；阿帕鲁胺；比卡鲁胺', '与 ESR1 同源的核受体，去势抵抗性前列腺癌阶段出现 AR 扩增、剪接变体与点突变，是核受体耐药的第二个范例。', '', '', 920, NULL, 'PREDICTED_ONLY', 1, '肿瘤'),
('P37231', 'PPARG', '过氧化物酶体增殖物激活受体 γ', '核受体', '核受体 NR1C 家族', 'FAMILY_NUCLEAR', 'DISEASE_METABOLIC', 'MODALITY_SMALL', 'PHASE_APPROVED', 'Adipogenesis / insulin sensitization', '2 型糖尿病；脂肪代谢障碍', '吡格列酮；罗格列酮', '噻唑烷二酮类的靶点，改善胰岛素敏感性但伴随体重增加与水肿；全激动剂与选择性调节剂的疗效-副作用分离是核受体药理的核心议题。', '', '', 505, '1FM6,1PRG', 'EXPERIMENTAL_STRUCTURE', 1, '代谢'),
('Q15116', 'PDCD1', '程序性细胞死亡蛋白 1（PD-1）', '免疫检查点受体', 'CD28 免疫受体家族', 'FAMILY_CHECKPOINT', 'DISEASE_ONCOLOGY,DISEASE_IMMUNE', 'MODALITY_BIO', 'PHASE_APPROVED', 'PD-1/PD-L1 免疫检查点', '黑色素瘤；非小细胞肺癌；晚期实体瘤', '纳武利尤单抗；帕博利珠单抗；信迪利单抗', 'T 细胞抑制性共受体，与 PD-L1 结合后招募 SHP2 削弱 TCR 信号；阻断后可恢复抗肿瘤免疫，但只在部分患者与部分瘤种有效，是最典型的「生物标志物决定成败」靶点。', 'SAFETY_IMMUNO', 'MQIPQAPWPVVWAVLQLGWRPGWFLDSPDRPWNPPTFSPALLVVTEGDNATFTCSFSNTSESFVLNWYRMSPSNQTDKLAAFPEDRSQPGQDCRFRVTQLPNGRDFHMSVVRARRNDSGTYLCGAISLAPKAQIKESLRAELRVTERRAEVPTAHPSPSPRPAGQFQTLVVGVVGGLLGSLVLLVWVLAVICSRAARGTIGARRTGQPLKEDPSAVPVFSVDYGELDFQWREKTPEPPVPCVPEQTEYATIVFPSGMGTSSPARRGSADGPRSAQPLRPEDGHCSWPL', 288, NULL, 'PREDICTED_ONLY', 1, '肿瘤 · 免疫'),
('P01375', 'TNF', '肿瘤坏死因子', '细胞因子', 'TNF 超家族', 'FAMILY_CYTOKINE', 'DISEASE_INFLAMM,DISEASE_IMMUNE', 'MODALITY_BIO', 'PHASE_APPROVED', 'TNF signaling / NF-κB', '类风湿关节炎；强直性脊柱炎；炎症性肠病', '阿达木单抗；英夫利西单抗；依那西普', '三聚体形式的促炎细胞因子，抗 TNF 生物制剂是自身免疫病的第一批重磅单抗；也是「抗药抗体与免疫原性」问题的经典场景。', 'SAFETY_IMMUNO', 'MSTESMIRDVELAEEALPKKTGGPQGSRRCLFLSLFSFLIVAGATTLFCLLHFGVIGPQREEFPRDLSLISPLAQAVRSSSRTPSDKPVAHVVANPQAEGQLQWLNRRANALLANGVELRDNQLVVPSEGLYLIYSQVLFKGQGCPSTHVLLTHTISRIAVSYQTKVNLLSAIKSPCQRETPEGAEAKPWYEPIYLGGVFQLEKGDRLSAEINRPDYLDFAESGQVYFGIIAL', 233, '2E7A,2AZ5', 'EXPERIMENTAL_STRUCTURE', 1, '炎症 · 免疫'),
('Q9BYF1', 'ACE2', '血管紧张素转换酶 2', '羧肽酶', 'ACE 家族', 'FAMILY_PROTEASE', 'DISEASE_INFECTION,DISEASE_CARDIO', 'MODALITY_SMALL', 'PHASE_NONE', 'RAAS 反向轴 / SARS-CoV-2 入侵', 'COVID-19；心血管疾病', '无获批药物', 'SARS-CoV-2 的功能性受体，同时把 Ang II 切成 Ang(1-7) 负向调节肾素-血管紧张素系统；本库中它与 AGTR1 构成一对方向相反的通路节点，可用来演示「同一通路内的靶点选择」。', '', '', 805, '28KD,3D0G', 'EXPERIMENTAL_STRUCTURE', 0, '感染 · 心血管'),
('P04637', 'TP53', '细胞肿瘤抗原 p53', '转录因子', 'p53 家族', 'FAMILY_OTHER', 'DISEASE_ONCOLOGY,DISEASE_RARE', 'MODALITY_NONE', 'PHASE_NONE', 'p53 细胞周期阻滞与凋亡', 'Li-Fraumeni 综合征；多种实体瘤', '无直接获批药物（MDM2 抑制剂间接）', '最常见的抑癌基因，约半数肿瘤携带 TP53 突变；因缺乏可成药的结合口袋，长期被视为「不可成药」。本库把它保留为「无成药先例」的对照靶点。', '', '', 393, '1GZH', 'NO_STRUCTURE', 0, '肿瘤 · 罕见病');
